PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE assignment (assignment_id TEXT, ticket_id TEXT, queue TEXT, assignee_id TEXT, assigned_at TEXT, reason TEXT, PRIMARY KEY (assignment_id), FOREIGN KEY (ticket_id) REFERENCES ticket (ticket_id), FOREIGN KEY (assignee_id) REFERENCES employee (employee_id));
CREATE TABLE category (category_id TEXT, name TEXT, default_queue TEXT, is_sensitive INTEGER, default_priority TEXT, PRIMARY KEY (category_id));
CREATE TABLE department (department_id TEXT, name TEXT, location TEXT, PRIMARY KEY (department_id));
CREATE TABLE employee (employee_id TEXT, full_name TEXT, email TEXT, department_id TEXT, manager_id TEXT, role TEXT, employment_type TEXT, location TEXT, hire_date TEXT, status TEXT, PRIMARY KEY (employee_id), UNIQUE (email), FOREIGN KEY (department_id) REFERENCES department (department_id), FOREIGN KEY (manager_id) REFERENCES employee (employee_id));
CREATE TABLE kb_policy_version (kb_id TEXT, version_id TEXT, PRIMARY KEY (kb_id, version_id), FOREIGN KEY (kb_id) REFERENCES knowledge_article (kb_id), FOREIGN KEY (version_id) REFERENCES policy_version (version_id));
CREATE TABLE knowledge_article (kb_id TEXT, title TEXT, category_id TEXT, body TEXT, status TEXT, published_at TEXT, PRIMARY KEY (kb_id), FOREIGN KEY (category_id) REFERENCES category (category_id));
CREATE TABLE message (message_id TEXT, ticket_id TEXT, sender_id TEXT, sender_role TEXT, message_type TEXT, sent_at TEXT, body TEXT, PRIMARY KEY (message_id), FOREIGN KEY (ticket_id) REFERENCES ticket (ticket_id), FOREIGN KEY (sender_id) REFERENCES employee (employee_id));
CREATE TABLE message_citation (message_id TEXT, version_id TEXT, kb_id TEXT, snippet TEXT, PRIMARY KEY (message_id, version_id), FOREIGN KEY (message_id) REFERENCES message (message_id), FOREIGN KEY (version_id) REFERENCES policy_version (version_id), FOREIGN KEY (kb_id) REFERENCES knowledge_article (kb_id));
CREATE TABLE policy_document (policy_id TEXT, title TEXT, category_id TEXT, audience TEXT, owner_department_id TEXT, PRIMARY KEY (policy_id), FOREIGN KEY (category_id) REFERENCES category (category_id), FOREIGN KEY (owner_department_id) REFERENCES department (department_id));
CREATE TABLE policy_version (version_id TEXT, policy_id TEXT, version_no INTEGER, effective_from TEXT, effective_to TEXT, key_rules TEXT, summary TEXT, PRIMARY KEY (version_id), FOREIGN KEY (policy_id) REFERENCES policy_document (policy_id));
CREATE TABLE resolution (resolution_id TEXT, ticket_id TEXT, resolved_at TEXT, resolution_code TEXT, cited_version_id TEXT, business_minutes_to_resolve INTEGER, PRIMARY KEY (resolution_id), UNIQUE (ticket_id), FOREIGN KEY (ticket_id) REFERENCES ticket (ticket_id), FOREIGN KEY (cited_version_id) REFERENCES policy_version (version_id));
CREATE TABLE sla (sla_id TEXT, ticket_id TEXT, priority TEXT, first_response_due TEXT, resolution_due TEXT, paused_minutes INTEGER, first_responded_at TEXT, business_minutes_to_first_response INTEGER, first_response_met INTEGER, resolution_met INTEGER, PRIMARY KEY (sla_id), UNIQUE (ticket_id), FOREIGN KEY (ticket_id) REFERENCES ticket (ticket_id));
CREATE TABLE ticket (ticket_id TEXT, employee_id TEXT, category_id TEXT, subject TEXT, created_at TEXT, priority TEXT, is_sensitive INTEGER, is_ambiguous INTEGER, missing_context INTEGER, PRIMARY KEY (ticket_id), FOREIGN KEY (employee_id) REFERENCES employee (employee_id), FOREIGN KEY (category_id) REFERENCES category (category_id));
CREATE TABLE ticket_status_event (event_id TEXT, ticket_id TEXT, from_status TEXT, to_status TEXT, event_at TEXT, actor_id TEXT, PRIMARY KEY (event_id), FOREIGN KEY (ticket_id) REFERENCES ticket (ticket_id), FOREIGN KEY (actor_id) REFERENCES employee (employee_id));
COMMIT;
